function renderTable(v){
  const p=S.players[v.pid];const ut=SL.userTeam();if(!p)return '';const neg=S.market.negs.find(n=>n.pid===v.pid);
  const done=v.result;const log=done?v.result.log:neg?neg.log:[];const fromT=v.fromTeam!=null?S.teams[v.fromTeam]:null;
  const stage=neg?neg.stage:'done';const mood=neg?neg.mood:(done&&done.mood)||50;const moodC=mood>=65?'#4fd18e':mood>=40?'#f0b44c':'#f07a6e';
  const agentNm=(neg&&neg.agent)||v.agent;const otherName=stage==='club'&&fromT?fromT.name+' 단장':p.name;const hid=hidOf(p);const ovT=hid?(()=>{const r=SL.ovrRange(p);return r.k<25?'추정 ?':`추정 ${r.lo}~${r.hi}`;})():`종합 ${Math.round(SL.calcOvr(p))}`;
  const title=(neg&&neg.mode==='renew')||v.mode==='renew'?'재계약 협상':stage==='club'?'이적료 협상':'계약 협상';
  let h=`<div class="pv tbl2"><div class="pvbar gut"><button aria-label="뒤로" onclick="UI.back()">←</button><span class="t">${title}</span>${neg?`<span class="small" style="margin-left:auto;color:var(--on-navy-dim)">남은 제시 ${neg.maxRounds-neg.rounds}회${neg.second?' · 두 번째 자리':''}</span>`:''}</div>
  <div class="table-top gut"><div class="seats"><div>${stage==='club'&&fromT?emblem(fromT,64):face(p,64)}<div class="nm">${esc(otherName)}</div><div class="rl">${stage==='club'&&fromT?`${esc(p.name)} 보유 구단`:`${p.pos} · ${p.age}세 · ${ovT}${agentNm?` · 대리인 ${esc(agentNm)}`:''}`}</div></div><div class="vs">VS</div><div>${emblem(ut,64)}<div class="nm">단장 (나)</div><div class="rl">현금 ${Ms(ut.cash)}</div></div></div><div class="desk"></div>
  ${(neg&&stage!=='club')||done?`<div class="mood">협상 분위기 <b style="color:${moodC}">${mood>=65?'우호적':mood>=40?'신중':'냉랭'}</b><div class="track"><i style="width:${mood}%;background:${moodC}"></i></div></div>`:''}</div>
  <div class="content gut" style="padding-bottom:12px">${negCtx(p,neg,fromT)}<div class="chat" id="chat">${bubbles(log,{player:p.name,agent:agentNm?agentNm+' (대리인)':p.name,club:fromT?fromT.name:'구단'})}</div>`;
  if(done){h+=`<div class="${done.done||done.pending?'okbox':'warnbox'}">${esc(done.msg||'')}</div><button class="primary big" onclick="UI.back()">${done.done?'선수 화면으로':'돌아가기'}</button></div></div>`;return h;}
  if(!neg){h+=`<div class="warnbox">협상 기한이 지나 테이블이 정리되었습니다.</div><button class="primary big" onclick="UI.back()">돌아가기</button></div></div>`;return h;}
  h+=`</div><div class="offerform gut">`;const f=ui.form;
  if(stage==='club'){const st=Math.max(100,Math.round(neg.ask*0.05/100)*100);h+=`<label for="tf_fee">${neg.os?`이적 합의금 (만원) · ${esc(fromT?fromT.name:'')} 요구 약 ${Ms(neg.ask)}`:`이적료 (만원) · 시장가치 ${Ms(SL.calcValue(p))}`}</label><div class="stepper"><button aria-label="감소" onclick="UI.bump('fee',-${st})">−</button><input id="tf_fee" type="number" value="${f.fee}" onchange="UI.setF('fee',+this.value)"><button aria-label="증가" onclick="UI.bump('fee',${st})">＋</button></div><div style="height:10px"></div>${(()=>{const C=commits(ut,p.id);return `<div class="mline impact"><span>이적료를 내면 남는 자금 <b>${Ms(ut.cash-(f.fee||0))}</b></span><span>그 뒤 개인 협상 (연봉·계약금 별도)</span>${C.parts.length?`<span class="w100">아직 남은 지출·일: ${C.parts.join(' · ')}</span>`:''}</div>`;})()}<div class="btns"><button class="ghost" onclick="UI.leaveTable()">자리에서 일어나기</button><button class="primary" onclick="UI.tableSubmit()">이적료 제안</button></div>`;}
  else{const step=Math.max(10,Math.round(neg.demand*0.04/10)*10);const signCost=neg.mode==='sign'&&!neg.major?Math.round(SL.calcValue(p)*0.1):0;const total=(neg.fee||0)+(f.bonus||0)+signCost;
    h+=`<div class="two"><div><label for="tf_sal">연봉 (만원/년)</label><div class="stepper"><button aria-label="연봉 감소" onclick="UI.bump('salary',-${step})">−</button><input id="tf_sal" type="number" value="${f.salary}" onchange="UI.setF('salary',+this.value)"><button aria-label="연봉 증가" onclick="UI.bump('salary',${step})">＋</button></div></div>
    <div><label for="tf_bonus">계약금 (만원)</label><div class="stepper"><button aria-label="계약금 감소" onclick="UI.bump('bonus',-${step*2})">−</button><input id="tf_bonus" type="number" value="${f.bonus}" onchange="UI.setF('bonus',+this.value)"><button aria-label="계약금 증가" onclick="UI.bump('bonus',${step*2})">＋</button></div></div></div>
    ${(()=>{const d=neg.revealed||Math.round((neg.hint[0]+neg.hint[1])/2);return `<div class="quick"><span class="muted small">빠르게</span>${[['요구 −10%',Math.round(d*0.9/10)*10],['요구대로',d],['요구 +10%',Math.round(d*1.1/10)*10]].map(([l,v])=>`<button class="sm ${f.salary===v?'primary':'ghost'}" onclick="UI.setF('salary',${v})">${l}</button>`).join('')}</div>`;})()}
    <label style="margin-top:8px">계약 기간${neg.fgn1?' <span class="muted small">(새 외국인은 1년만)</span>':''}</label><div class="yrs">${(neg.fgn1?[1]:[1,2,3,4]).map(y=>`<button class="${f.years===y?'on':''}" onclick="UI.setF('years',${y})">${y}년</button>`).join('')}</div>
    ${neg.wantPromise?`<label class="toggle" for="tf_prom"><input id="tf_prom" type="checkbox" ${f.promise?'checked':''} onchange="UI.setF('promise',this.checked)"> 주전 출장 약속 <span class="muted small">(어기면 사기 크게 하락)</span></label>`:''}
    <div class="muted small" style="margin:6px 0">우리 제시 <b>${f.years}년 총액 ${Ms((f.salary||0)*(f.years||1)+(f.bonus||0)+signCost)}</b>${signCost?` (FA 기본 계약금 ${Ms(signCost)} 포함)`:''} · ${neg.major?`선수 요구 ${neg.yrsAsk}년 총액 <b>${Ms(SL.faM(p.id)?SL.faM(p.id).ask.tot:0)}</b>`:neg.revealed?`요구 수준 약 <b>${Ms(neg.revealed)}</b>`:`예상 요구 ${Ms(neg.hint[0])}~${Ms(neg.hint[1])}`} · 계약금은 연봉으로 일부 환산 · 즉시 지출 ${Ms(total)}${neg.fee?` (이적료 포함)`:''}</div>
    ${(()=>{const pay=SL.payroll(ut);const old=neg.mode==='renew'&&p.contract?p.contract.salary:0;const C=commits(ut,p.id);const left=ut.cash-total;return `<div class="mline impact"><span>계약하면 남는 자금 <b class="${left<C.da?'dn':''}">${Ms(left)}</b></span><span>연봉 총액 ${Ms(pay)} → <b>${Ms(pay-old+(f.salary||0))}</b></span>${C.parts.length?`<span class="w100">아직 남은 지출·일: ${C.parts.join(' · ')}</span>`:''}</div>`;})()}
    <div class="btns"><button class="ghost" onclick="UI.leaveTable()">자리에서 일어나기</button><button class="primary" onclick="UI.tableSubmit()">조건 제시</button></div>`;}
  h+=`</div></div>`;return h;
}
