  setDrive(k){const e=SL.setDrive(k);if(e){toast(e,3500);return;}closeModal();sfx('win',0.5);autosave();render();},
  driveMenu(){const I=SL.driveInfo(SL.userTeam());modal(`<h3>감독 지시</h3><div class="muted small" style="margin-bottom:8px">걸어 두면 ${SL.DRIVE_DAYS}경기 동안 효과. 한 시즌 ${SL.DRIVE_USES}번 · 담당 코치가 없으면 효과 절반${I.cur?` · 지금 「${esc(I.cur.name)}」 ${I.cur.left}경기 남음`:''}</div>${I.list.map(x=>`<div class="prow" onclick="UI.setDrive('${x.k}')"><div class="grow"><div class="nm">${esc(x.name)}</div><div class="sub">${esc(x.what)} · ${x.has?esc(x.dept)+' 있음':'<span class="dim">'+esc(x.dept)+' 없음 (절반)</span>'}</div></div><span class="chip ${I.cur||I.left<=0?'':'g'}">${I.left}번 남음</span></div>`).join('')}`);},
