  counterOffer(id){const v=+$('#ct_amt').value;const o=SL.state().market.offers.find(x=>x.id===id);if(!o)return;const lg=ui.offerLog[id]=ui.offerLog[id]||[];lg.push({who:'me',text:`${M(v)}이면 보내드리겠습니다.`});
    const t=SL.state().teams[o.team];const r=SL.respondOffer(id,'counter',v);lg.push({who:'club',text:r.msg.split(t.name+': ').join('').split(SL.josa(t.name,'이','가')+' ').join('')});ui.ct=null;
    if(!SL.state().market.offers.find(x=>x.id===id))ui.view.msg=r.msg;autosave();render();},
  respond(id,action){const lg=ui.offerLog[id]=ui.offerLog[id]||[];if(action==='accept')lg.push({who:'me',text:'제안을 받아들이겠습니다.'});else if(action==='reject')lg.push({who:'me',text:'이번 제안은 정중히 거절합니다.'});const o0=S.market.offers.find(x=>x.id===id);const pid0=o0&&o0.pid;const from0=pid0!=null?S.players[pid0].teamId:null;const r=SL.respondOffer(id,action);if(action==='accept'&&r.ok)sfx('cash');const fare=action==='accept'&&r.ok&&pid0!=null&&S.players[pid0]&&S.players[pid0].teamId!==from0;if(fare)setTimeout(()=>farewellCard(pid0),80);
    autosave();if(ui.view&&ui.view.type==='offer'){ui.view.msg=r.msg;ui.view.ok=r.ok&&action==='accept';render();}else{if(!fare)toast(r.msg,4000);render();}},
  startGame(){const lg=SL.startDay();if(lg)guideMark('game');if(!lg){SL.finishDay();autosave();render();return;}autosave();render();if(!lg.paCount&&lg.inn<=1)sfx('playball',0.5);},
  step(kind){const lg=SL.state().liveGame;if(!lg)return;{const ck=chgKey(lg);if(ck&&ui.chgSeen!==ck){if(['pa','pitch','half'].includes(kind)&&ui.chgShow!==ck){ui.chgShow=ck;render();return;}ui.chgSeen=ck;}}const ut=SL.userTeam();const my=lg.home===ut.id?1:0;const sc0=lg.score[my],op0=lg.score[1-my];let ev;if(kind==='pitch')ev=SL.stepPitch(lg);else if(kind==='pa')ev=SL.stepPA(lg);else if(kind==='half')ev=SL.stepHalf(lg);else if(kind==='hl'){ev=SL.stepPA(lg);let guard=0;while(!lg.done&&!isKeyMoment(lg,my)&&guard++<120)ev=SL.stepPA(lg);if(!lg.done)toast(keyWhy(lg,my),1800);}
    else if(kind==='to'){const N=ui.toInn||7;let guard=0,stop=null;while(!lg.done&&lg.inn<N&&guard++<400){ev=SL.stepPA(lg);if(ui.toKey&&!lg.done&&lg.inn<N&&lg.inn>=3&&isKeyMoment(lg,my)&&Math.abs(lg.score[0]-lg.score[1])<=2&&(lg.bases[1]||lg.bases[2])){stop=keyWhy(lg,my);break;}}
      if(!lg.done){if(!stop)ui.stepMode='hl';toast(stop?`${stop} — 멈췄습니다 (구간 진행은 그대로)`:`${lg.inn}회부터 직접 진행합니다 (장면마다)`,2600);}}
    else ev=SL.stepGame(lg);
    if(ev&&(kind==='pitch'||kind==='pa'||kind==='hl'))playSfx(ev,lg.score[my]>sc0);
    try{stadSfx(ev,lg,my,kind);}catch(e){}
    if(lg.done){sfx(lg.score[my]>lg.score[1-my]?'win':'lose',0.7);}autosave();render();},
  ledger(pid){const p=SL.P(pid);if(p)modal(ledgerModal(p));},
  renewAll(){const ps=S.pendingFA.map(id=>S.players[id]).filter(p=>p&&!p.grudge);if(!ps.length){toast('일괄 재계약할 선수가 없습니다.');return;}modal(`<h3>일괄 재계약</h3><div class="small" style="margin-bottom:8px">협상 없이 선수 요구액 그대로 계약합니다 (외국인·32세 이상 1년, 나머지 2년). 서운함이 남은 선수는 빠집니다.</div>${ps.map(p=>`<div class="small asrow">${esc(p.name)} · ${SL.POS_KO[p.pos]||p.pos} ${p.age}세 — 연봉 ${Ms(p.contract?p.contract.salary:0)} → <b>${Ms(SL.renewDemandOf(p))}</b></div>`).join('')}<div style="height:10px"></div><div class="btns"><button class="primary" onclick="UI.renewAllGo()">${ps.length}명 재계약</button><button class="ghost" onclick="UI.closeModal()">취소</button></div>`);},
  renewAllGo(){const r=SL.renewAll();toast(`${r.length}명 재계약${r.skip&&r.skip.length?` · 예산 부족으로 ${r.skip.length}명 제외`:''}`,4000);UI.closeModal();autosave();render();},
